package io.github.heapy.icu4k.text

import io.github.heapy.icu4k.util.Enumeration
import kotlin.test.*

class TransliteratorRegistryTest {
    @Test fun parsedResourcesMatchIndependentIcu78Fingerprints() {
        val rules = listOf("", "# empty", "a > b;", "::[a]; a > b;", "::Null;", "::[a]; ::Null;", "a > b; ::Null; b > c;", "::Null; a > b;", "a > b; ::Null;", "::[ab]; a > b; ::Null; b > cc;")
        // Generated by a standalone Java program using only the pinned ICU4J jar.
        val expected = intArrayOf(1990348688,1990348688,1990348688,1990348688,-2086269730,-1852751716,-2086269730,-1852751716,1009933840,1009933840,-1200128880,1009933840,-481012450,-1039424420,1243939422,-1876153892,1557415774,-1876153892,-1306608032,-1039424420)
        var index = 0
        for(rule in rules) for(direction in 0..1) {
            val registry=TransliteratorRegistryCore(RegistryFixtureHost)
            var calls=0
            registry.putResourceSupplier("X-Y",{ calls++; rule },direction,true)
            var hash=1
            fun add(value: Any?) { hash=31*hash+(value?.toString()?.hashCode() ?: 0) }
            repeat(2) {
                val alias=StringBuilder("prefix:")
                val result=registry.get("x-y",alias)
                add(alias); add(result?.getID()); add(result?.filterValue?.toPattern(false)); add(result?.rules(false)); add(result?.rules(true))
                if(result!=null) for(input in listOf("","abc","aabbcc")) {
                    val text=ReplaceableString(input)
                    result.transliterate(text,0,text.length())
                    add(text.toString())
                }
            }
            add(calls)
            assertEquals(expected[index++],hash,"$rule/$direction")
        }
    }
    @Test fun embeddedLocaleLookupAndCacheIdentity() {
        val store=TransliteratorRegistryStore()
        for((id,direction) in listOf("el-Latin" to 0,"el_GR-Latin" to 0,"Latin-el" to 1,"Any-el" to 1,"el-Latin/UNGEGN" to 0,"el-Latin/missing" to 0)) {
            val entry=store.find(id)!!
            val locale=entry[0] as TransliteratorRegistryStore.LocaleEntry
            assertEquals(1091995653,locale.rule.hashCode(),id)
            assertEquals(direction,locale.direction,id)
            assertSame(entry,store.find(id),id)
        }
        assertNull(store.find("Greek-el"))
        assertFalse(store.getAvailableIDs().hasMoreElements())
    }
    private fun values(e: Enumeration<String>) = buildList { while(e.hasMoreElements())add(e.nextElement()) }
    @Test fun visibilityOrderingAndLiveEnumerations() {
        val store=TransliteratorRegistryStore()
        store.put("Latin-Greek/v","one",true)
        store.put("latin-greek","two",true)
        store.put("LATIN-GREEK/W","three",true)
        assertEquals(listOf("Latin-Greek/v","latin-greek","LATIN-GREEK/W"),values(store.getAvailableIDs()))
        assertEquals(listOf("","v","W"),values(store.getAvailableVariants("LATIN","greek")))
        val ids=store.getAvailableIDs()
        store.put("LATIN-GREEK/V","replacement",true)
        assertEquals("Latin-Greek/v",ids.nextElement())
        val variants=store.getAvailableVariants("Latin","Greek")
        store.put("Latin-Greek/Z","four",true)
        assertTrue(variants.hasMoreElements())
        assertFailsWith<ConcurrentModificationException>{ variants.nextElement() }
        assertFailsWith<ConcurrentModificationException>{ ids.nextElement() }
        store.put("Latin-Greek/v","hidden",false)
        assertEquals(listOf("","W","Z"),values(store.getAvailableVariants("Latin","Greek")))
        store.remove("Latin-Greek"); store.remove("Latin-Greek/W"); store.remove("Latin-Greek/Z")
        assertFalse(store.getAvailableSources().hasMoreElements())
        val missing=store.getAvailableTargets("missing")
        assertFalse(missing.hasMoreElements())
        assertFailsWith<NullPointerException>{ missing.nextElement() }
    }
    @Test fun supplierNullRetryFailureAndAliasCaching() {
        var calls=0
        val resource=TransliteratorRegistryCore.ResourceEntry({ calls++; if(calls<3)null else "a>b;" },0)
        assertNull(resource.getResource()); assertNull(resource.getResource())
        assertEquals("a>b;",resource.getResource()); assertEquals("a>b;",resource.getResource()); assertEquals(3,calls)
        val registry=TransliteratorRegistryCore(RegistryFixtureHost)
        var attempts=0
        registry.putResourceSupplier("X-Y",{ if(++attempts==1)throw IllegalArgumentException("retry"); "::Null;" },0,true)
        assertFailsWith<IllegalArgumentException>{ registry.get("X-Y",StringBuilder()) }
        repeat(2) {
            val alias=StringBuilder("prefix:")
            assertNull(registry.get("X-Y",alias))
            assertEquals("prefix:Null;",alias.toString())
        }
        assertEquals(2,attempts)
    }
}
